#include <WiFi.h>

const char* ssid = "ESP32-S3-Robot";
const char* password = "12345678";
WiFiServer server(80);

void setup() {
  Serial.begin(115200);
  Serial.println("Kiem tra trinh bien dịch web...");

  WiFi.softAP(ssid, password);
  server.begin();
}

void loop() {
  WiFiClient client = server.available();
  if (client) {
    client.println("HTTP/1.1 200 OK");
    client.println("Content-Type: text/html");
    client.println("");
    client.println("<h1>ESP32-S3 Ready</h1>");
    client.stop();
  }
  delay(1000);
}
